<script setup lang="ts">
import {usePageActivity} from '../page-activity';
const listLoaded=ref(false);
const pageActive=usePageActivity();
import Modal from '../components/Modal.vue';
import EmptyState from '../components/EmptyState.vue';
import Pagination from '../components/Pagination.vue';

import {useScopedRefresh} from '../scoped-refresh';
import {useLatestRead,useOperationRead,collectPages} from '../data-sync';
import { useFeedback } from '../feedback';
import { markDirty } from '../workspace';
import { formatBeijing,stateLabel,roleNames,rolesText,actionLabel } from '../presentation';
import { ref,computed } from 'vue';
import { listDepartments,type Department } from '../api';
import { courseApi,errorText,tag,type User,type Employee,type Page } from '../course-api';
const pageSize=ref(20),auditPageSize=ref(20),auditLoading=ref(false),auditLoaded=ref(false),auditError=ref('');
const items=ref<User[]>([]),employees=ref<Employee[]>([]),departments=ref<Department[]>([]),q=ref(''),page=ref(1),total=ref(0),busy=ref(false),error=ref(''),notice=ref(''),open=ref(false),selected=ref<User|null>(null),reset=ref<User|null>(null),password=ref('');
const blank=()=>({username:'',password:'',employee_id:null as string|null,roles:['EMPLOYEE'],department_ids:[] as string[],status:'ACTIVE'});
const form=ref(blank());
const audits=ref<{id:string;occurred_at:string;action_code:string;outcome:string;request_id:string;actor_user_id:string|null;actor_username?:string|null}[]>([]),auditPage=ref(1),auditTotal=ref(0);
const reading=ref(false),boundUsers=ref<User[]>([]),listRead=useLatestRead(),auditRead=useLatestRead(),optionsRead=useLatestRead(),operate=useOperationRead(busy,error);
const employeeOptions=computed(()=>employees.value.filter(e=>!boundUsers.value.some(u=>u.employee_id===e.id&&u.id!==selected.value?.id)));
const unavailableDepartments=computed(()=>form.value.department_ids.filter(id=>!departments.value.some(d=>d.id===id&&d.status==='ACTIVE')));
const selectionWarning=computed(()=>{if(!open.value||selected.value&&form.value.status==='DISABLED')return '';if(form.value.employee_id&&!employeeOptions.value.some(e=>e.id===form.value.employee_id))return '原选择的员工已被其他账号绑定或不可用，请重新选择。';if(form.value.roles.some(r=>r!=='ADMIN')&&form.value.employee_id&&!employeeOptions.value.some(e=>e.id===form.value.employee_id&&['PROBATION','ACTIVE','EXIT_PROCESSING'].includes(e.employment_status)))return '原选择的员工已不具备有效在职状态，请重新选择。';if(unavailableDepartments.value.length)return '原负责部门已停用或不可用，请取消该选择后重新分配。';return '';});
async function loadAudit(strict=false){const query=`/users/audit-events?page=${auditPage.value}&page_size=${auditPageSize.value}` as const;try{await auditRead.run(query,()=>courseApi<Page<typeof audits.value[number]>>(query),{start:()=>{auditLoading.value=true;auditError.value='';},success:data=>{audits.value=data.items;auditTotal.value=data.total;auditLoaded.value=true;},failure:e=>{auditError.value=errorText(e);},finish:()=>{auditLoading.value=false;}});}catch(e){if(strict===true)throw e;}}
async function load(strict=false){const query=`/users?q=${encodeURIComponent(q.value)}&page=${page.value}&page_size=${pageSize.value}` as const;try{await listRead.run(query,()=>courseApi<Page<User>>(query),{start:()=>{reading.value=true;error.value='';},success:data=>{items.value=data.items;total.value=data.total;listLoaded.value=true;},failure:e=>{error.value=errorText(e);},finish:()=>{reading.value=false;}});}catch(e){if(strict===true)throw e;}}
async function options(){await optionsRead.run('options',async()=>{const [es,ds,us]=await Promise.all([collectPages(page=>courseApi<Page<Employee>>(`/users/employee-options?page=${page}&page_size=100`)),collectPages(page=>listDepartments('',page,100)),collectPages(page=>courseApi<Page<User>>(`/users?page=${page}&page_size=100`))]);return {es,ds,us};},{success:({es,ds,us})=>{employees.value=es;departments.value=ds;boundUsers.value=us;}});}
async function edit(row?:User){if(busy.value)return;await operate('edit:'+String(row?.id||'new'),async()=>{await options();const latest=row?boundUsers.value.find(u=>u.id===row.id):null;if(row&&!latest)throw new Error('账号记录已变化，请重新查询后操作');return latest||null;},latest=>{selected.value=latest;form.value=latest?{username:latest.username,password:'',employee_id:latest.employee_id,roles:[...latest.roles],department_ids:[...latest.department_ids],status:latest.status}:blank();open.value=true;reset.value=null;});}
async function openReset(row:User){if(busy.value)return;await operate('reset:'+row.id,async()=>{const rows=await collectPages(page=>courseApi<Page<User>>(`/users?q=${encodeURIComponent(row.username)}&page=${page}&page_size=100`));const latest=rows.find(u=>u.id===row.id);if(!latest)throw new Error('账号记录已变化，请重新查询后操作');return latest;},latest=>{reset.value=latest;open.value=false;password.value='';});}
async function save(){if(busy.value)return;if(selectionWarning.value){error.value=selectionWarning.value;return;}busy.value=true;error.value='';notice.value='';try{const {username,password,...rest}=form.value;
  if(selected.value)await courseApi(`/users/${encodeURIComponent(selected.value.id)}`,'PATCH',rest,tag(selected.value));
  else await courseApi('/users','POST',{username,password,employee_id:rest.employee_id,roles:rest.roles,department_ids:rest.department_ids});
  markDirty('/users',false);notice.value='账号已保存；角色或状态变更后，该账号需要重新登录';open.value=false;await load();
}catch(e){error.value=errorText(e);}finally{form.value.password='';busy.value=false;}}
async function savePassword(){if(busy.value)return;if(!reset.value)return;busy.value=true;error.value='';notice.value='';try{await courseApi(`/users/${encodeURIComponent(reset.value.id)}/password`,'POST',{password:password.value},tag(reset.value));markDirty('/users',false,'password');notice.value='密码已重置，该账号需要重新登录';reset.value=null;await load();}catch(e){error.value=errorText(e);}finally{password.value='';busy.value=false;}}
const {scopeLocked,scopeFailure,retryScope,scopeStyle}=useScopedRefresh(async()=>{await Promise.all([options(),load(true),...(auditLoaded.value?[loadAudit(true)]:[])]);},['users','employees','departments']);
useFeedback(notice,error,'/users');
</script>
<template><div :style="scopeStyle" class="business-page"><p v-if="scopeLocked" class="verification" role="status">{{scopeFailure||'加载中…'}}<button v-if="scopeFailure" @click="retryScope">重试</button></p><main v-show="!scopeLocked"><div class="section-heading"><h1>用户管理</h1><button :disabled="busy" @click="edit()">创建账号</button></div><p class="muted">管理账号、员工绑定和角色。业务账号须绑定在职员工，不能修改本人角色或停用本人。</p><p v-if="busy&&!open&&!reset" role="status">正在读取操作所需数据…</p><p v-if="error" class="error feedback" role="alert">{{error}}</p><p v-if="notice" class="success feedback" role="status">{{notice}}</p>
<section class="card"><form class="search-row" @submit.prevent="page=1;load()"><label>账号搜索<input v-model="q" maxlength="64"></label><button :disabled="busy">查询</button></form><p v-if="!scopeLocked&&(reading||!listLoaded&&!error)" role="status">加载中…</p><EmptyState v-else-if="listLoaded&&!error&&!items.length" text="暂无账号数据"/><div v-else-if="listLoaded&&!error" class="table-scroll"><table><thead><tr><th>账号</th><th>员工</th><th>有效角色</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in items" :key="row.id"><td>{{row.username}}</td><td>{{employees.find(e=>e.id===row.employee_id)?(employees.find(e=>e.id===row.employee_id)?.full_name+' · '+employees.find(e=>e.id===row.employee_id)?.employee_no):'未绑定员工'}}</td><td>{{rolesText(row.roles)}}</td><td>{{row.status==='ACTIVE'?'启用':'停用'}}</td><td><button class="text-button" :disabled="busy" @click="edit(row)">编辑 / 角色 / 停用</button><button class="text-button" :disabled="busy" @click="openReset(row)">重置密码</button></td></tr></tbody></table></div><Pagination :page="page" :page-size="pageSize" :total="total" :busy="reading" @page="page=$event;load()" @size="pageSize=$event;page=1;load()"/></section>
<Modal :return-focus="operate.opener.value" v-if="open" :title="selected?'编辑账号':'创建账号'" :busy="busy" :error="error" :concealed="scopeLocked" @retry="retryScope" wide @close="open=false;form.password=''"><form @submit.prevent="save"><fieldset :disabled="busy"><p v-if="selectionWarning" class="error" role="alert">{{selectionWarning}}</p><div class="form-columns"><label>账号<input v-model="form.username" required maxlength="64" :disabled="!!selected" autocomplete="off"></label><label v-if="!selected">初始密码<input v-model="form.password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><label>绑定员工<select aria-label="绑定员工" v-model="form.employee_id"><option :value="null">不绑定（仅系统管理员账号）</option><option v-if="form.employee_id&&!employeeOptions.some(e=>e.id===form.employee_id)" disabled :value="form.employee_id">原绑定员工不可用，请核对</option><option v-for="e in employeeOptions" :key="e.id" :value="e.id">{{e.employee_no}} · {{e.full_name}} · {{stateLabel(e.employment_status)}}</option></select></label><label v-if="selected">状态<select aria-label="状态" v-model="form.status"><option value="ACTIVE">启用</option><option value="DISABLED">停用</option></select></label></div><h3>基础角色</h3><div class="checks"><label v-for="role in ['EMPLOYEE','MANAGER','HR','ADMIN']" :key="role"><input v-model="form.roles" type="checkbox" :value="role" :aria-label="roleNames[role]">{{roleNames[role]}}</label></div><template v-if="form.roles.includes('MANAGER')"><h3>直接负责部门</h3><div class="checks"><label v-for="id in unavailableDepartments" :key="id"><input v-model="form.department_ids" type="checkbox" :value="id">原负责部门已不可用（请取消）</label><label v-for="d in departments.filter(x=>x.status==='ACTIVE')" :key="d.id"><input v-model="form.department_ids" type="checkbox" :value="d.id">{{d.name}}</label></div></template><p class="muted">移除主管角色时，请先取消负责部门。角色变更或停用后，该账号的所有设备都需重新登录。</p><div class="form-actions"><button>保存账号</button><button type="button" class="secondary" data-modal-cancel>取消</button></div></fieldset></form></Modal>
<Modal :return-focus="operate.opener.value" v-if="reset" :title="'重置 '+reset.username+' 的密码'" scope="password" :busy="busy" :error="error" :concealed="scopeLocked" @retry="retryScope" @close="reset=null;password=''"><form data-dirty-scope="password" @submit.prevent="savePassword"><label>新密码<input v-model="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><div class="form-actions"><button :disabled="busy">确认重置密码</button><button type="button" class="secondary" data-modal-cancel>取消</button></div></form></Modal>
<section class="card"><div class="section-heading"><h2>重要操作审计</h2><button class="secondary" @click="loadAudit()">读取审计</button></div><p class="muted">查看账号和业务变更记录，可通过请求编号核对具体操作。</p><p v-if="auditError" class="error feedback" role="alert">{{auditError}}</p><p v-if="auditLoading" role="status">正在加载审计…</p><EmptyState v-else-if="auditLoaded&&!auditError&&!audits.length" text="暂无审计记录"/><div v-else-if="!auditError&&audits.length" class="table-scroll"><table><thead><tr><th>北京时间 / 操作</th><th>操作者</th><th>结果 / 请求编号</th></tr></thead><tbody><tr v-for="event in audits" :key="event.id"><td>{{formatBeijing(event.occurred_at)}}<br>{{actionLabel(event.action_code)}}</td><td><small>{{event.actor_username||'系统 / 未认证事件'}}</small></td><td>{{stateLabel(event.outcome)}}<br><small>{{event.request_id}}</small></td></tr></tbody></table></div><Pagination v-if="auditLoaded" :page="auditPage" :page-size="auditPageSize" :total="auditTotal" :busy="auditLoading" label="审计分页" @page="auditPage=$event;loadAudit()" @size="auditPageSize=$event;auditPage=1;loadAudit()"/></section>
</main></div></template>
